mapper.select:
SELECT BASE.BBS_ID AS bbsId , BASE.BBS_NM_KEY AS bbsNmKey , B.MESSAGE_CN AS bbsName , BASE.BBS_TY AS bbsTy , BASE.LAYOUT_TY_NM AS bbsTyNm , BASE.STATUS_COLOR AS statusColor , BASE.SORTING_SQ AS sortingSq FROM ( SELECT A.BBS_ID , A.BBS_NM_KEY , A.BBS_TY -- 저장값은 공통코드 DETAIL_CODE_VALUE(예: GENERAL)인 경우가 많음. ID와 VALUE 모두 매칭 , (SELECT B1.MESSAGE_CN FROM CM_CODE_DETAIL A1 LEFT JOIN CM_MESSAGE_LANG B1 ON B1.LANG_KEY = A1.CODE_LANG_KEY AND B1.LANG_CODE = #{languageCode} AND B1.CMPNY_CD = A1.CMPNY_CD WHERE A1.CODE_ID = 'CMMNCODE.BBS.001' AND A1.CMPNY_CD = A.CMPNY_CD AND (A1.DETAIL_CODE_VALUE = A.BBS_TY OR A1.DETAIL_CODE_ID = A.BBS_TY) LIMIT 1 ) AS LAYOUT_TY_NM , CASE WHEN A.USE_FL = 'N' THEN 'RED' WHEN ( (SELECT COUNT(*) FROM CM_NTT_COMMENT C WHERE C.NTT_SQ IN ( SELECT NTT_SQ FROM CM_NTT WHERE BBS_ID = A.BBS_ID AND DELETE_FL = 'N' AND USE_FL = 'Y' ) AND C.USE_FL = 'Y' AND C.APPROVED_FL = 'N' ) + (SELECT COUNT(*) FROM CM_NTT N WHERE N.BBS_ID = A.BBS_ID AND N.DELETE_FL = 'Y' AND N.USE_FL = 'Y' ) ) > 0 THEN 'ORANGE' ELSE 'GREEN' END AS STATUS_COLOR , A.SORTING_SQ FROM CM_BBS A WHERE A.CMPNY_CD = #{cmpnyCd}
AND A.BBS_TY = #{bbsTy}
AND A.BBS_NAME LIKE CONCAT('%', #{searchKeyword}, '%')
UNION ALL SELECT 'BBS-POPUP' AS BBS_ID , 'menu.BBS.titlenm.popupNotice' AS BBS_NM_KEY , '' AS BBS_TY , '' AS LAYOUT_TY_NM , (SELECT CASE WHEN COUNT(POPUP_SQ) > 0 THEN 'GREEN' ELSE 'RED' END FROM CM_NTT_POPUP A WHERE A.CMPNY_CD = #{cmpnyCd} AND A.START_DT < SYSDATE() AND A.END_DT > SYSDATE() AND A.USE_FL = 'Y') AS STATUS_COLOR , 2147483647 AS SORTING_SQ FROM DUAL ) BASE LEFT JOIN CM_MESSAGE_LANG B ON B.LANG_KEY = BASE.BBS_NM_KEY AND B.LANG_CODE = #{languageCode} AND B.CMPNY_CD = #{cmpnyCd} ORDER BY BASE.SORTING_SQ ASC

SELECT COALESCE(MAX(SORTING_SQ), 0)
  FROM CM_BBS
 WHERE CMPNY_CD = #{cmpnyCd}

SELECT COUNT(*)
  FROM CM_NTT
 WHERE BBS_ID = #{bbsId}
   AND CMPNY_CD = #{cmpnyCd}
   AND IFNULL(USE_FL,'Y') = 'Y'

SELECT COUNT(*)
  FROM CM_NTT_COMMENT C
 INNER JOIN CM_NTT N ON N.NTT_SQ = C.NTT_SQ
 WHERE N.BBS_ID = #{bbsId}
   AND N.CMPNY_CD = #{cmpnyCd}

SELECT CASE WHEN COUNT(*) > 0 THEN 'ORANGE' ELSE NULL END
  FROM CM_NTT A
 WHERE A.BBS_ID = #{bbsId}
   AND A.CMPNY_CD = #{cmpnyCd}
   AND A.DELETE_FL = 'Y'
   AND A.USE_FL = 'Y'

