INSERT INTO CM_BBS_CATEGORY (
    CATEGORY_SQ, BBS_ID, CMPNY_CD, CATEGORY_NM, SORTING_SQ, CREATION_ID, UPDATE_ID
) VALUES (
    CAST(#{categorySq} AS DECIMAL(30,0)), #{bbsId}, #{cmpnyCd}, #{categoryNm}, #{sortingSq}, #{creationId}, #{updateId}
)

INSERT INTO CM_BBS_AUTHOR (
    AUTHOR_SQ, BBS_ID, CMPNY_CD, TARGET_TY, TARGET_CD,
    READING_FL, WRITING_FL, REPLY_FL, MANAGER_FL, SORTING_SQ,
    CREATION_ID, UPDATE_ID
) VALUES (
    CAST(#{authorSq} AS DECIMAL(30,0)), #{bbsId}, #{cmpnyCd}, #{targetTy}, #{targetCd},
    #{readingFl}, #{writingFl}, #{replyFl}, #{managerFl}, #{sortingSq},
    #{creationId}, #{updateId}
)

mapper.update:
UPDATE CM_BBS SET
    BBS_NM_KEY = #{bbsNmKey}
  , BBS_CN = #{bbsCn}
  , BBS_TY = #{bbsTy}
  , LAYOUT_TY = #{layoutTy}
  , REPLY_FL = #{replyFl}
  , COMMENT_FL = #{commentFl}
  , LIKE_FL = #{likeFl}
  , DISLIKE_FL = #{dislikeFl}
  , ATCHMNFL_FL = #{atchmnflFl}
  , NOTICE_FL = #{noticeFl}
  , ENFRC_SECRET_FL = #{enfrcSecretFl}
  , ANONYMOUS_FL = #{anonymousFl}
  , COMMENT_CONFM_FL = #{commentConfmFl}
  , RESVE_FL = #{resveFl}
  , CATEGORY_FL = #{categoryFl}
  , MAX_FILE_SIZE = #{maxFileSize}
  , MAX_FILE_COUNT = #{maxFileCount}
  , PERM_EXTSN = #{permExtsn}
  , POSTS_PER_PAGE = #{postsPerPage}
  , TITLE_LENGTH = #{titleLength}
  , VALID_FROM = STR_TO_DATE(#{validFrom}, '%Y-%m-%d %H:%i:%s')NULL
  , VALID_TO = STR_TO_DATE(#{validTo}, '%Y-%m-%d %H:%i:%s')NULL
  , SORTING_SQ = #{sortingSq}
  , USE_FL = #{useFl}
  , UPDATE_ID = #{updateId}
  , UPDATE_DT = CURRENT_TIMESTAMP
 WHERE BBS_ID = #{bbsId}
   AND CMPNY_CD = #{cmpnyCd}

UPDATE CM_BBS SET SORTING_SQ = #{sortingSq}, UPDATE_ID = #{updateId}, UPDATE_DT = CURRENT_TIMESTAMP
 WHERE BBS_ID = #{bbsId}
   AND CMPNY_CD = #{cmpnyCd}

UPDATE CM_BBS_CATEGORY SET
    CATEGORY_NM = #{categoryNm}
  , SORTING_SQ = #{sortingSq}
  , UPDATE_ID = #{updateId}
  , UPDATE_DT = CURRENT_TIMESTAMP
 WHERE CATEGORY_SQ = CAST(#{categorySq} AS DECIMAL(30,0))
   AND BBS_ID = #{bbsId}
   AND CMPNY_CD = #{cmpnyCd}

UPDATE CM_BBS_AUTHOR SET
    TARGET_TY = #{targetTy}
  , TARGET_CD = #{targetCd}
  , READING_FL = #{readingFl}
  , WRITING_FL = #{writingFl}
  , REPLY_FL = #{replyFl}
  , MANAGER_FL = #{managerFl}
  , SORTING_SQ = #{sortingSq}
  , UPDATE_ID = #{updateId}
  , UPDATE_DT = CURRENT_TIMESTAMP
 WHERE AUTHOR_SQ = CAST(#{authorSq} AS DECIMAL(30,0))
   AND BBS_ID = #{bbsId}
   AND CMPNY_CD = #{cmpnyCd}

UPDATE CM_NTT
   SET DELETE_FL = 'N'
     , DELETE_DT = NULL
     , UPDATE_ID = #{updateId}
     , UPDATE_DT = CURRENT_TIMESTAMP
 WHERE NTT_SQ = CAST(#{nttSq} AS DECIMAL(30,0))
   AND BBS_ID = #{bbsId}
   AND CMPNY_CD = #{cmpnyCd}

UPDATE CM_NTT
   SET USE_FL = 'N'
     , UPDATE_ID = #{updateId}
     , UPDATE_DT = CURRENT_TIMESTAMP
 WHERE NTT_SQ = CAST(#{nttSq} AS DECIMAL(30,0))
   AND BBS_ID = #{bbsId}
   AND CMPNY_CD = #{cmpnyCd}

UPDATE CM_NTT A
 INNER JOIN CM_BBS BB ON BB.BBS_ID = A.BBS_ID AND BB.CMPNY_CD = #{cmpnyCd}
   SET A.DELETE_FL = 'N'
     , A.DELETE_DT = NULL
     , A.UPDATE_ID = #{updateId}
     , A.UPDATE_DT = CURRENT_TIMESTAMP
 WHERE A.BBS_ID = #{bbsId}
   AND A.DELETE_FL = 'Y'
   AND IFNULL(A.USE_FL, 'Y') = 'Y'

UPDATE CM_NTT A
 INNER JOIN CM_BBS BB ON BB.BBS_ID = A.BBS_ID AND BB.CMPNY_CD = #{cmpnyCd}
   SET A.USE_FL = 'N'
     , A.UPDATE_ID = #{updateId}
     , A.UPDATE_DT = CURRENT_TIMESTAMP
 WHERE A.BBS_ID = #{bbsId}
   AND A.DELETE_FL = 'Y'
   AND IFNULL(A.USE_FL, 'Y') = 'Y'

UPDATE CM_NTT_POPUP
   SET XCNTS = #{xcnts}
     , YDNTS = #{ydnts}
     , WIDTH = #{width}
     , VRTICL = #{vrticl}
     , START_DT = STR_TO_DATE(#{startDt}, '%Y-%m-%d %H:%i:%s')NULL
     , END_DT = STR_TO_DATE(#{endDt}, '%Y-%m-%d %H:%i:%s')NULL
     , HIDE_FL = #{hideFl}
     , USE_FL = #{useFl}
 WHERE POPUP_SQ = CAST(#{popupSq} AS DECIMAL(30,0))
   AND NTT_SQ = CAST(#{nttSq} AS DECIMAL(30,0))
   AND BBS_ID = #{bbsId}
   AND CMPNY_CD = #{cmpnyCd}

UPDATE CM_NTT
   SET RD_CNT = (
           SELECT COUNT(*)
             FROM CM_NTT_VIEW
            WHERE NTT_SQ = CAST(#{nttSq} AS DECIMAL(30,0))
              AND BBS_ID = #{bbsId}
              AND CMPNY_CD = #{cmpnyCd}
       )
     , LIKE_CNT = (
           SELECT COUNT(*)
             FROM CM_NTT_VOTE
            WHERE NTT_SQ = CAST(#{nttSq} AS DECIMAL(30,0))
              AND BBS_ID = #{bbsId}
              AND CMPNY_CD = #{cmpnyCd}
              AND VOTE_GB = 'L'
       )
     , DISLIKE_CNT = (
           SELECT COUNT(*)
             FROM CM_NTT_VOTE
            WHERE NTT_SQ = CAST(#{nttSq} AS DECIMAL(30,0))
              AND BBS_ID = #{bbsId}
              AND CMPNY_CD = #{cmpnyCd}
              AND VOTE_GB = 'D'
       )
     , FAVORITE_CNT = (
           SELECT COUNT(*)
             FROM CM_NTT_FAVORITE
            WHERE NTT_SQ = CAST(#{nttSq} AS DECIMAL(30,0))
              AND BBS_ID = #{bbsId}
              AND CMPNY_CD = #{cmpnyCd}
       )
 WHERE NTT_SQ = CAST(#{nttSq} AS DECIMAL(30,0))
   AND BBS_ID = #{bbsId}
   AND CMPNY_CD = #{cmpnyCd}

mapper.insert:
INSERT IGNORE INTO CM_NTT_VOTE (NTT_SQ, BBS_ID, CMPNY_CD, MBRSH_SQ, VOTE_GB)
SELECT CAST(#{nttSq} AS DECIMAL(30,0)), #{bbsId}, #{cmpnyCd}, M.MBRSH_SQ, #{voteGb}
  FROM CM_USER_ORGNZT_MBRSH M
  INNER JOIN CM_USER U ON U.USER_ID = M.USER_ID
 WHERE M.CMPNY_CD = #{cmpnyCd}
   AND M.USER_ID = #{userId}
   AND M.USE_FL = 'Y'
 LIMIT 1

